ruleToc.chapterList:
@js:
let v = [],
		list = [];
JSON.parse(result).list.map($=>{

//分卷判定
		V = $.name;
		if(v[v.length-1]!=V&&!/^\s*$/.test(V)){
				v.push(V)
				list.push({
						name: '📖['+V+']📖',
						volume: true
					})
			}

$.bookChapters.map($=>{
		return list.push({
				name: $.name,
				url: `https://readbook-service-freebook.cread.com/cx/itf/chapterRead?bookId=${$.bookid}&chapterId=${$.id}`,
				info: `章节字数：${$.wordCount}　更新时间：${$.updateDate}`
			});
	});
});
v.length<2?list.filter($=>!$.volume):list

exploreUrl:
@js:
let url = String(source.getVariable()!=""?source.getVariable():source.getKey()).replace(/\/$/, '') 
let arr = []
let push = (title, url, type) => arr.push({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
})

push("🏷️全部分类🏷️", "", 1)
let res = org.jsoup.Jsoup.parse(java.ajax(url))
let lis = res.select('.nav a');
for (let i = 0; i < lis.length; i++) {
    let text = lis[i].text();
    let href = url + String(lis[i].attr('href')).replace(/\.html/g,"_\{\{page\}\}\.html");
    push(text, href, 0.25);
}
JSON.stringify(arr)

